import AppKit
import XCTest
@testable import MacPanelPlatform

final class ClipboardTests: XCTestCase {
    func testEveryMarkerRejectsWholeCopyBeforeReadingText() {
        for marker in ["org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
                       "org.nspasteboard.AutoGeneratedType", "de.petermaurer.TransientPasteboardType",
                       "com.agilebits.onepassword"] {
            let history = ClipboardHistory()
            history.setEnabled(true, changeCount: 0)
            var reads = 0
            history.observe(changeCount: 1, types: [marker], source: nil) {
                reads += 1
                return "synthetic secret"
            }
            XCTAssertEqual(reads, 0, marker)
            XCTAssertTrue(history.items.isEmpty, marker)
        }
    }

    func testOptInBaselineDisableDedupAndCapacity() {
        let history = ClipboardHistory(capacity: 2)
        history.observe(changeCount: 1, types: [], source: nil) { "disabled" }
        XCTAssertTrue(history.items.isEmpty)
        history.setEnabled(true, changeCount: 1)
        history.observe(changeCount: 1, types: [], source: nil) { "preexisting" }
        XCTAssertTrue(history.items.isEmpty)
        for (count, text) in [(2, "one"), (3, "two"), (4, "one"), (5, "three")] {
            history.observe(changeCount: count, types: [], source: nil) { text }
        }
        XCTAssertEqual(history.items, ["three", "one"])
        history.setEnabled(false, changeCount: 5)
        XCTAssertTrue(history.items.isEmpty)
    }

    func testIgnoredSourcesAndOversizedOrEmptyText() {
        let history = ClipboardHistory(maximumBytes: 4)
        history.setEnabled(true, changeCount: 0)
        for (count, source) in ["com.apple.Passwords", "com.apple.keychainaccess"].enumerated() {
            history.observe(changeCount: count + 1, types: [], source: source) {
                XCTFail("ignored application content must not be read")
                return "no"
            }
        }
        history.observe(changeCount: 3, types: [], source: nil) { "" }
        history.observe(changeCount: 4, types: [], source: nil) { "한글" }
        XCTAssertTrue(history.items.isEmpty)
    }

    func testPrivatePasteboardScansAllItemsAndDoesNotReplayRejectedChange() {
        let board = NSPasteboard.withUniqueName()
        defer { board.releaseGlobally() }
        let watcher = ClipboardWatcher(pasteboard: board)
        watcher.setEnabled(true)
        let publicItem = NSPasteboardItem()
        publicItem.setString("synthetic public", forType: .string)
        let hiddenItem = NSPasteboardItem()
        hiddenItem.setData(Data(), forType: .init("org.nspasteboard.ConcealedType"))
        board.clearContents()
        board.writeObjects([publicItem, hiddenItem])
        watcher.poll()
        watcher.poll()
        XCTAssertTrue(watcher.history.items.isEmpty)
        board.clearContents()
        board.setString("synthetic accepted", forType: .string)
        watcher.poll()
        XCTAssertEqual(watcher.history.items, ["synthetic accepted"])
        watcher.setEnabled(false)
    }
}
